        g_assert_not_reached();
    }

    /* Hardware Reduced = 1 and use PSCI 0.2+ */
    fadt->flags = cpu_to_le32(1 << ACPI_FADT_F_HW_REDUCED_ACPI);
    fadt->arm_boot_flags = cpu_to_le16(bootflags);

